using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Musikbox {public static class EmbeddedArtwork {
 public static List<TagChange> Plan(IEnumerable<Song> songs,string path,bool append=false){Validate(path);return songs.GroupBy(s=>Path.GetFullPath(s.Source),StringComparer.OrdinalIgnoreCase).Select(g=>new TagChange{Song=g.First(),Source=g.Key,Target=g.Key,ArtworkPath=path,AppendArtwork=append,Description="Titelcover in Originaldatei speichern"}).ToList();}
 public static void Validate(string path){if(!File.Exists(path))throw new FileNotFoundException("Cover nicht erreichbar.",path);var b=File.ReadAllBytes(path);bool png=b.Length>8&&b.Take(8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}),jpeg=b.Length>3&&b[0]==255&&b[1]==216&&b[2]==255;if(!png&&!jpeg)throw new ArgumentException("Titelcover benötigt ein JPEG- oder PNG-Bild.");if(b.Length>20*1024*1024)throw new ArgumentException("Cover ist größer als 20 MB.");}
 public static void Write(string file,string path,bool append){Validate(path);byte[] bytes=File.ReadAllBytes(path);using(var f=TagLib.File.Create(file)){var picture=new TagLib.Picture(new TagLib.ByteVector(bytes)){Type=TagLib.PictureType.FrontCover,MimeType=bytes[0]==137?"image/png":"image/jpeg",Description="Frontcover"};var existing=f.Tag.Pictures.Where(p=>append||p.Type!=TagLib.PictureType.FrontCover).ToList();existing.Add(picture);f.Tag.Pictures=existing.ToArray();f.Save();}using(var check=TagLib.File.Create(file))if(!check.Tag.Pictures.Any(p=>p.Type==TagLib.PictureType.FrontCover&&p.Data.Data.SequenceEqual(bytes)))throw new IOException("Das eingebettete Cover konnte nach dem Speichern nicht bestätigt werden.");}
}}